/**
 * The viewBox for marks that are not 24x24, keyed the same way.
 *
 * Simple Icons pulled Visual Studio Code over Microsoft's trademark policy, so
 * its glyph is the silhouette from the official icon we already ship at
 * static/integrations/vscode.svg -- which is drawn on a 100x100 grid.
 */
export const brandIconViewBox: Record<string, string> = {
	vscode: '0 0 100 100',
	myst: '0 0 100 100',
	restructuredtext: '0 0 512 512'
};

